/* Chicago Bulls DNA — bulls red and black, ninety-six swagger */
.theme-chicago-bulls {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.973 0 0);
  --surface-2: oklch(0.943 0 0);
  --fg: oklch(0.174 0.004 286.0);
  --fg-muted: oklch(0.470 0.010 286.0);
  --accent: oklch(0.545 0.211 17.0);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.000 0 0);
  --line: oklch(0.922 0 0);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.545 0.211 17.0);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Big Shoulders", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.12em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-chicago-bulls h1,
.theme-chicago-bulls h2,
.theme-chicago-bulls h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-chicago-bulls { --font-ui: var(--font-display); }
.theme-chicago-bulls h1, .theme-chicago-bulls h2 { text-transform: uppercase; font-weight: 800; }
.theme-chicago-bulls h1::after { content: ""; display: block; height: 5px; width: 6rem; margin-top: 0.6rem; background: linear-gradient(90deg, var(--accent) 0 50%, var(--accent-2) 50% 100%); }
.theme-chicago-bulls button { text-transform: uppercase; letter-spacing: 0.08em; font-weight: 700; }

/* team */
.theme-chicago-bulls { background-image: linear-gradient(180deg, oklch(0.97 0 0), transparent 240px); }
.theme-chicago-bulls h1 { color: var(--accent); -webkit-text-stroke: 1.5px #000000; }
.theme-chicago-bulls h2::after { content: ""; display: block; width: 4rem; height: 4px; background: #000000; margin-top: 0.5rem; }


/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
